using System;
using Xunit;

public class CircuitBreakerTests
{
    private static readonly Exception BoomErr = new InvalidOperationException("boom");

    private static string Boom() => throw BoomErr;

    [Fact]
    public void TripsOpenAfterConsecutiveFailures()
    {
        var b = new CircuitBreaker(3, 10);
        for (int i = 0; i < 3; i++)
        {
            var ex = Assert.Throws<InvalidOperationException>(() => b.Call(Boom, 0));
            Assert.Same(BoomErr, ex);
        }
        Assert.Throws<CircuitOpenException>(() => b.Call(() => "should not run", 0));
    }

    [Fact]
    public void FailsFastWithoutCallingFnWhileOpen()
    {
        var b = new CircuitBreaker(1, 100);
        Assert.Throws<InvalidOperationException>(() => b.Call(Boom, 0));
        bool called = false;
        Assert.Throws<CircuitOpenException>(() => b.Call(() => { called = true; return "x"; }, 1));
        Assert.False(called);
    }

    [Fact]
    public void HalfOpenTrialAfterTimeoutSuccessCloses()
    {
        var b = new CircuitBreaker(1, 10);
        Assert.Throws<InvalidOperationException>(() => b.Call(Boom, 0));
        Assert.Equal("ok", b.Call(() => "ok", 10));
        Assert.Equal("still-fine", b.Call(() => "still-fine", 11));
    }

    [Fact]
    public void HalfOpenFailureReopensAndResetsClock()
    {
        var b = new CircuitBreaker(1, 10);
        Assert.Throws<InvalidOperationException>(() => b.Call(Boom, 0));
        Assert.Throws<InvalidOperationException>(() => b.Call(Boom, 10));
        Assert.Throws<CircuitOpenException>(() => b.Call(() => "too soon", 15));
        Assert.Equal("ok now", b.Call(() => "ok now", 20));
    }
}
